void __stdcall UI_InitializeHirelingIconsUI() {
    gnHireDisplayMode = 0;
    ui::SetUIFlag(UI_HIREICONS, UI_SET, 0);
    int32_t nRegHideValue = 0;
    Storm::Source::SReg::SRegLoadValue("Diablo II", "PopupHireling", 0, &nRegHideValue);
    if (nRegHideValue) {
      return;
    }

    gbHireIconsVisible = 1;
}

static void __stdcall DrawHealthBar(uint32_t nRosterGUID, uint32_t nPetType, int32_t nX) {
    int nHp = nPetType ? GAME::RosterPets::GetRosterPerHPPercent(nRosterGUID) : GAME::Roster::GetRosterHP(nRosterGUID);
    if (!nHp) {
      return;
    }

    int nBarRightX = nX + 46; // steer-ok: the original keeps the right edge in a stack slot across the palette calls; folded it loses MATCH here and in the three callers
    int nHpPercent = (nHp <= 0 ? 0 : nHp) < 100 ? (nHp <= 0 ? 0 : nHp) : 100;

    int nBarEndX = nHpPercent * 46 / 100 + nX;
    if (!HealthBarColorsInitialized) {
      HealthBarColorsInitialized = true;
      HealthBarGreen = D2Win::Src::D2WinPalette::D2GFX_GetColorFromCurrentPallete(0, 0x80, 0);
      HealthBarYellowish = D2Win::Src::D2WinPalette::D2GFX_GetColorFromCurrentPallete(0xc0, 0xc0, 0);
      HealthBarRed = D2Win::Src::D2WinPalette::D2GFX_GetColorFromCurrentPallete(0xff, 0, 0);
    }

    uint8_t nColor = HealthBarGreen;
    if (nHpPercent < 50) {
      nColor = HealthBarYellowish;
    }
    if (nHpPercent < 25) {
      nColor = HealthBarRed;
    }

    D2gfx::D2GFX::D2GFX_DrawSolidRectEx(nX, 14, nBarEndX, 19, nColor, DRAW_SOLID);
    D2gfx::D2GFX::D2GFX_DrawSolidRectEx(nBarEndX, 14, nBarRightX, 19, 0, DRAW_SOLID);
}

static void __stdcall UI_DrawHirelingNameFromUnit(D2UnitStrc * pUnit, int32_t nX, int32_t nY) {
    uint16_t wszName[32];
    if (!pUnit) {
      return;
    }

    memset(wszName, 0, 0x40);
    D2Lang::Unicode::UNISYS::WSTRING_PutWideCharIntoBuffer(wszName, UNIT::CUnit::GetName(pUnit), 0x20);
    wszName[0x1f] = L'\0';
    DrawHirelingName(nX, nY, 0, wszName);
}

static BOOL __stdcall UI_DrawPartyMembersHirelingIcons(int * pnY, int * pnYOffset, int * pnX, D2UnitStrc * pUnit) {
    D2RosterStrc* pRoster;
    uint32_t nRosterGUID;
    int32_t nRosterCharClass;
    DC6* pClassIcon;
    int nX;
    D2GfxDataStrc sGfxData;
    uint32_t nPlayerGUID;
    int nIconDrawX;
    bool bDrewAny = false;
    uint16_t nPartyId = UNIT::CUnit::GetPlayerUnitPartyId(pUnit);
    if (!pUnit) {
      nPlayerGUID = -1;
    } else {
      nPlayerGUID = pUnit->nUnitGUID;
    }
    if (nPartyId != 0xffff && !gnHireDisplayMode) {
      uint16_t nRosterPartyId;
      pRoster = GAME::Roster::GetNextRosterPlayer(nullptr);
      if (pRoster) {
        for (; pRoster; pRoster = GAME::Roster::GetNextRosterPlayer(pRoster)) {
          nRosterPartyId = GAME::Roster::GetRosterPartyId(pRoster);
          if (nPartyId == nRosterPartyId) {
            nRosterGUID = GAME::Roster::GetRosterGUID(pRoster);
            if (nRosterGUID != nPlayerGUID) {
              nRosterCharClass = GAME::Roster::GetRosterCharType(pRoster);
              switch (nRosterCharClass) {
                case 0:
                  pClassIcon = ClassIcons[0];
                break;
                case 1:
                  pClassIcon = ClassIcons[1];
                break;
                case 4:
                  pClassIcon = ClassIcons[2];
                break;
                case 3:
                  pClassIcon = ClassIcons[3];
                break;
                case 2:
                  pClassIcon = ClassIcons[4];
                break;
                case 6:
                  pClassIcon = ClassIcons[5];
                break;
                default:
                  continue;
                case 5:
                  pClassIcon = ClassIcons[6];
                break;
              }

              if (pClassIcon) {
                DrawHealthBar(nRosterGUID, 0, *pnX);
                nIconDrawX = *pnY;
                nX = *pnX;
                UI_DrawHirelingNameFromString(GAME::Roster::GetRosterName(pRoster), nX, nIconDrawX);
                if (*pnYOffset) {
                  *pnY -= *pnYOffset;
                  *pnYOffset = 0;
                } else {
                  *pnYOffset = 10;
                  *pnY += 10;
                }

                memset(&sGfxData, 0, sizeof(sGfxData));
                sGfxData.pDC6 = pClassIcon;
                D2gfx::D2GFX::D2GFX_DrawImage(&sGfxData, *pnX, 0x3c, -1, DRAW_TRANSPARENT, nullptr);
                *pnX += 0x38;
                bDrewAny = true;
              }
            }
          }
        }

        if (bDrewAny) {
          return 1;
        }
      }
    }

    return 0;
}

static BOOL __stdcall HIRELING_DrawPortraitIcon(D2UnitStrc * pUnit, int * pnYToggle, int * pnY, int * pnX) {
    D2GfxDataStrc sGfxData;
    memset(&sGfxData, 0, sizeof(sGfxData));
    int32_t nRosterGUID;
    sGfxData.pDC6 = GetRosterIcon(pUnit, 7, &nRosterGUID, nullptr);
    if (!sGfxData.pDC6) {
      return 0;
    }

    DrawHealthBar(nRosterGUID, 7, *pnX);
    UI_DrawHirelingNameFromUnit(UNIT::CUnit::UNITS_FindClientSideUnit(nRosterGUID, UNIT_MONSTER), *pnX, *pnY);
    if (*pnYToggle) {
      *pnY -= *pnYToggle;
      *pnYToggle = 0;
    } else {
      *pnYToggle = 10;
      *pnY += 10;
    }

    gnHireIconDrawX = *pnX;
    gnHireIconDrawY = *pnY;
    if (gnHireIconHoverY && gnHireIconHoverIndex) {
      DWORD dwNow;
      dwNow = GetTickCount();
      if (dwNow - gnHireIconHoverIndex >= 700) {
        gnHireIconHoverX = 1;
        D2gfx::D2GFX::D2GFX_DrawImage(&sGfxData, *pnX, 0x3c, -1, DRAW_LIGHTERSOLID, nullptr);
        *pnX += 0x38;
        return 1;
      }
    }
    if (gnHireIconHoverX) {
      D2gfx::D2GFX::D2GFX_DrawImage(&sGfxData, *pnX, 0x3c, -1, DRAW_LIGHTERSOLID, nullptr);
      *pnX += 0x38;
      return 1;
    }

    D2gfx::D2GFX::D2GFX_DrawImage(&sGfxData, *pnX, 0x3c, -1, DRAW_TRANSPARENT, nullptr);
    *pnX += 0x38;
    return 1;
}

static BOOL __stdcall HIRELING_DrawPetIcon(D2UnitStrc * pUnit, int * nX, int * pnYToggle, uint32_t nPetType, int * nY) {
    D2GfxDataStrc sGfxData;
    memset(&sGfxData, 0, sizeof(sGfxData));
    int32_t nRosterGUID;
    sGfxData.pDC6 = GetRosterIcon(pUnit, nPetType, &nRosterGUID, nullptr);
    if (!sGfxData.pDC6) {
      return 0;
    }

    DrawHealthBar(nRosterGUID, nPetType, *nX);
    int* pnXCursor = nX;
    GetAndDrawHirelingName(*nX, *nY, nPetType);
    if (*pnYToggle) {
      *nY -= *pnYToggle;
      *pnYToggle = 0;
    } else {
      *pnYToggle = 10;
      *nY += 10;
    }

    D2gfx::D2GFX::D2GFX_DrawImage(&sGfxData, *pnXCursor, 0x3c, -1, DRAW_TRANSPARENT, nullptr);
    *pnXCursor += 0x38;
    return 1;
}

static BOOL __stdcall HIRELING_DrawSummonIcon(D2UnitStrc * pUnit, int32_t * nY, int * pnYToggle, uint32_t nSkillId, int32_t * nX) {
    D2GfxDataStrc sGfxData;
    int32_t nRosterGUIDOut;
    int32_t nRosterCount = GAME::RosterPets::CountRostersForUnitFilterBySkill(pUnit, nSkillId);
    if (!nRosterCount) {
      return 0;
    }

    int32_t nRosterCountSaved = nRosterCount;
    memset(&sGfxData, 0, sizeof(sGfxData));
    uint32_t nSingleFlag = 0;
    sGfxData.pDC6 = GetRosterIcon(pUnit, nSkillId, &nRosterGUIDOut, &nSingleFlag);
    if (!sGfxData.pDC6) {
      return 0;
    }
    if (nRosterCount == 1 && nSingleFlag) {
      uint32_t nRosterGUID;
      nRosterGUID = GAME::RosterPets::GetRosterPetGUID(pUnit, nSkillId, 0);
      DrawHealthBar(nRosterGUID, nSkillId, *nX);
      nRosterCount = nRosterCountSaved;
    }

    UI_DrawSummonCount(nRosterCount, *nX);
    GetAndDrawHirelingName(*nX, *nY, nSkillId);
    if (*pnYToggle) {
      *nY -= *pnYToggle;
      *pnYToggle = 0;
    } else {
      *pnYToggle = 10;
      *nY += 10;
    }

    D2gfx::D2GFX::D2GFX_DrawImage(&sGfxData, *nX, 0x3c, -1, DRAW_TRANSPARENT, nullptr);
    *nX += 0x38;
    return 1;
}

